\begin{tikzpicture}
\begin{axis}[
    width=0.70\textwidth,
    height=0.45\textwidth,
    xmin=0, xmax=2.2,
    ymin=0, ymax=3.2,
    axis lines=left,
    xlabel={\(x\)},
    ylabel={\(y\)},
    xtick={0.3,1.1,1.9},
    xticklabels={\(a\),\(m\),\(b\)},
    ytick=\empty,
    grid=both,
    grid style={line width=.1pt, draw=gray!25},
]
\draw[fill=gray!18, draw=gray!60]
  (axis cs:0.3,0) rectangle (axis cs:1.9,{1+0.35*1.1+0.45*1.1^2});
\addplot[very thick, domain=0.3:1.9, samples=120] {1+0.35*x+0.45*x^2};
\addplot[only marks, mark=*] coordinates {(1.1,{1+0.35*1.1+0.45*1.1^2})};
\draw[dashed] (axis cs:1.1,0) -- (axis cs:1.1,{1+0.35*1.1+0.45*1.1^2});
\node[anchor=west] at (axis cs:1.18,2.05) {\(f(m)\)};
\node at (axis cs:1.1,0.65) {midpoint rectangle};
\end{axis}
\end{tikzpicture}

\begin{tikzpicture}
\begin{axis}[
    width=0.70\textwidth,
    height=0.45\textwidth,
    xmin=0, xmax=2.2,
    ymin=0, ymax=3.2,
    axis lines=left,
    xlabel={\(x\)},
    ylabel={\(y\)},
    xtick={0.3,1.9},
    xticklabels={\(a\),\(b\)},
    ytick=\empty,
    grid=both,
    grid style={line width=.1pt, draw=gray!25},
]
\addplot[fill=gray!18, draw=gray!60] coordinates {
  (0.3,0)
  (0.3,{1+0.35*0.3+0.45*0.3^2})
  (1.9,{1+0.35*1.9+0.45*1.9^2})
  (1.9,0)
  (0.3,0)
};
\addplot[very thick, domain=0.3:1.9, samples=120] {1+0.35*x+0.45*x^2};
\addplot[thick, dashed] coordinates {
  (0.3,{1+0.35*0.3+0.45*0.3^2})
  (1.9,{1+0.35*1.9+0.45*1.9^2})
};
\addplot[only marks, mark=*] coordinates {
  (0.3,{1+0.35*0.3+0.45*0.3^2})
  (1.9,{1+0.35*1.9+0.45*1.9^2})
};
\node at (axis cs:1.1,0.70) {trapezoid};
\node[anchor=west] at (axis cs:1.05,2.6) {secant line};
\end{axis}
\end{tikzpicture}

\begin{tikzpicture}
\begin{axis}[
    width=0.82\textwidth,
    height=0.48\textwidth,
    xmin=0, xmax=1.05,
    ymin=0, ymax=1.1,
    axis lines=left,
    xlabel={\(x\)},
    ylabel={\(y\)},
    xtick={0,0.25,0.5,0.75,1},
    ytick={0,0.5,1},
    grid=both,
    grid style={line width=.1pt, draw=gray!25},
]
% midpoint rectangles for exp(-x^2) on [0,1], n=4
\draw[fill=gray!14, draw=gray!55] (axis cs:0.0,0) rectangle (axis cs:0.25,0.9844964370054085);
\draw[fill=gray!14, draw=gray!55] (axis cs:0.25,0) rectangle (axis cs:0.5,0.8688150562628432);
\draw[fill=gray!14, draw=gray!55] (axis cs:0.5,0) rectangle (axis cs:0.75,0.676633846161729);
\draw[fill=gray!14, draw=gray!55] (axis cs:0.75,0) rectangle (axis cs:1.0,0.4650431881340563);
\addplot[very thick, domain=0:1, samples=150] {exp(-x^2)};
\node[anchor=west] at (axis cs:0.42,0.92) {\(y=e^{-x^2}\)};
\node[anchor=west] at (axis cs:0.42,0.22) {four midpoint rectangles};
\end{axis}
\end{tikzpicture}

